// Validate input. Body shape:
//   { trigger_kind: 'staging_auto' | 'production_manual' | 'scheduled',
//     target_env: string,
//     target_base_url: string | 'auto',     // 'auto' requires app_name
//     app_name?: string,                    // coolify_app_slots.app_name; when set, RPC derives URL + captures active_slot
//     story_id?: uuid,                      // when set, RPC emits qa_playwright_* story_entries
//     suite?: string, deploy_ref?: string, metadata?: object }
const body = $input.first().json.body ?? $input.first().json;
const valid = ['staging_auto', 'production_manual', 'scheduled'];
if (!valid.includes(body.trigger_kind)) {
  throw new Error(`trigger_kind must be one of: ${valid.join(', ')}`);
}
if (!body.target_env) throw new Error('target_env required');
const url = body.target_base_url;
if (!url) throw new Error('target_base_url required (or "auto" with app_name)');
if (url !== 'auto' && !/^https?:\/\//.test(url)) {
  throw new Error('target_base_url must be http(s)://... or "auto"');
}
if (url === 'auto' && !body.app_name) {
  throw new Error('target_base_url="auto" requires app_name');
}
return [{ json: {
  trigger_kind: body.trigger_kind,
  target_env: body.target_env,
  target_base_url: url,
  app_name: body.app_name ?? null,
  story_id: body.story_id ?? null,
  suite: body.suite ?? 'all',
  deploy_ref: body.deploy_ref ?? null,
  metadata: body.metadata ?? {}
} }];

// Enqueue via start_playwright_run RPC (service_role).
// When app_name is passed, the RPC consults resolve_deployed_url() to
// derive target_base_url from the live B/G slot and capture active_slot;
// when story_id is passed, the RPC emits qa_playwright_requested into the
// storyloop timeline.
const gw = $env.AISHA_GATEWAY_URL;
const tok = $env.AISHA_SERVICE_KEY;
const input = $input.first().json;
const res = await fetch(`${gw}/rest/v1/rpc/start_playwright_run`, {
  method: 'POST',
  headers: { 'content-type': 'application/json', apikey: tok, authorization: `Bearer ${tok}` },
  body: JSON.stringify({
    p_trigger_kind: input.trigger_kind,
    p_target_env: input.target_env,
    p_target_base_url: input.target_base_url,
    p_suite: input.suite,
    p_deploy_ref: input.deploy_ref,
    p_metadata: input.metadata,
    p_story_id: input.story_id,
    p_app_name: input.app_name
  })
});
if (!res.ok) {
  const text = await res.text();
  throw new Error(`start_playwright_run failed: ${res.status} ${text}`);
}
const run_id = (await res.json()).toString().replace(/"/g, '');
const approval = input.trigger_kind === 'production_manual';
return [{ json: { run_id, trigger_kind: input.trigger_kind, target_env: input.target_env, target_base_url: input.target_base_url, app_name: input.app_name, story_id: input.story_id, suite: input.suite, deploy_ref: input.deploy_ref, approval_required: approval } }];

// Audit + return. Approval gate is enforced inside svc-playwright-runner
// via get_next_playwright_run (which skips approval_required rows that
// have no approved_at). Production_manual runs sit queued until the
// admin calls approve_playwright_run RPC.
const gw = $env.AISHA_GATEWAY_URL;
const tok = $env.AISHA_SERVICE_KEY;
const i = $input.first().json;
await fetch(`${gw}/rest/v1/rpc/log_integration_action`, {
  method: 'POST',
  headers: { 'content-type': 'application/json', apikey: tok, authorization: `Bearer ${tok}` },
  body: JSON.stringify({
    p_integration: 'n8n',
    p_action_key: 'playwright.enqueued',
    p_payload: { run_id: i.run_id, trigger_kind: i.trigger_kind, target_env: i.target_env, target_base_url: i.target_base_url, app_name: i.app_name, story_id: i.story_id, suite: i.suite, deploy_ref: i.deploy_ref, approval_required: i.approval_required },
    p_tags: ['stack', 'qa', 'playwright', i.trigger_kind]
  })
});
return [{ json: { ok: true, run_id: i.run_id, approval_required: i.approval_required, message: i.approval_required ? 'Queued; awaiting admin approval (call approve_playwright_run RPC).' : 'Queued; runner will pick up within the poll interval.' } }];
